// Proof from the parent side: read the value the iframe wrote.
const hex = nb.get('picked_hex');
const clicks = nb.get('pick_count');
console.log('value that came back from the iframe:', hex, '(' + typeof hex + ')');
console.log('iframe reported', clicks, 'click(s)');

// Round-trip the other way: write from JS, and the iframe will highlight it.
// (Uncomment to try: nb.set('picked_hex', '#a855f7');)

return {
  picked_hex: { value: hex, type: typeof hex },      // string, set by the iframe
  pick_count: { value: clicks, type: typeof clicks },// number, set by the iframe
};
